const [count, setCount] = useState(0);

// читаем значение
<p>{count}</p>

// меняем — запускается перерисовка
<button onClick={() => setCount(count + 1)}>+1</button>

useEffect(() => {
  // выполняется после каждого рендера,
  // если изменилась зависимость count
  document.title = `Счёт: ${count}`;
}, [count]);

// пустой массив [] = один раз при монтировании
useEffect(() => {
  console.log('Компонент смонтирован');
}, []);

// обработчики — обычные функции
const handleIncrement = () => setCount(c => c + 1);
const handleInput = (event) => setText(event.target.value);

